fields.InputDefinition:
{
  "goal": "Open the 'Products' entity grid — navigate to http://localhost:4200/app/data-explorer/Data?entity=Products (or type 'Products' in the LEFT sidebar 'Search entities...' box and click the exact match). Wait for the grid to load. Then open Configure View (the sliders / 'Configure view settings' icon in the grid toolbar) and walk these sections IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) products-grid — the Products grid finishes loading with rows or a valid empty state; (2) columns-management — on the Configure View 'Columns' tab, the column-management UI shows 'Visible Columns' and 'Hidden Columns' lists; (3) column-format-editor — still on the Columns tab, click a column's paintbrush 'Format column' button to open the format-editor sub-panel (Format Type dropdown, alignment/style controls, live Preview); (4) smart-filter — switch to the 'Filters' tab, choose 'Smart Filter', and confirm the natural-language description textarea plus example chips render; (5) add-aggregate-dialog — switch to the 'Aggregates' tab and click 'Add Aggregate' to open the aggregate setup dialog (function + field + display-type choices); (6) aggregate-summary — complete the aggregate (e.g. a count or sum on a column) and confirm an aggregate result/summary value is shown. Keep going until every section has been visited. You do NOT need to save any configuration. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200/app/data-explorer/Data?entity=Products",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 90,
  "checkpoints": [
    {
      "name": "products-grid",
      "instruction": "open the Products entity grid",
      "assertions": [
        {
          "kind": "url",
          "urlPattern": "/app/data-explorer/Data"
        }
      ],
      "visualCriteria": [
        "The Products entity grid is loaded, showing data rows or a valid empty state"
      ]
    },
    {
      "name": "columns-management",
      "instruction": "Configure View > Columns tab shows column lists",
      "visualCriteria": [
        "The Configure View 'Columns' tab renders the column-management UI with 'Visible Columns' and 'Hidden Columns' lists"
      ]
    },
    {
      "name": "column-format-editor",
      "instruction": "open a column's Format editor",
      "visualCriteria": [
        "Clicking a column's paintbrush button opens the format-editor sub-panel with a Format Type selector, alignment/style controls, and a live Preview section"
      ]
    },
    {
      "name": "smart-filter",
      "instruction": "Filters tab > Smart Filter mode",
      "visualCriteria": [
        "Selecting 'Smart Filter' on the Filters tab reveals a natural-language description textarea plus example prompt chips"
      ]
    },
    {
      "name": "add-aggregate-dialog",
      "instruction": "Aggregates tab > Add Aggregate dialog",
      "visualCriteria": [
        "Clicking 'Add Aggregate' opens an aggregate setup dialog offering an aggregate function, a field choice, and a display-type option"
      ]
    },
    {
      "name": "aggregate-summary",
      "instruction": "configure an aggregate and see its result",
      "visualCriteria": [
        "An aggregate is configured and an aggregate result/summary value (a count/sum/average) is displayed, with no error"
      ]
    }
  ]
}
